# Instance copy of $DLC/servers/pasoe/bin/setenv.sh with one bash-ism fixed.
#!/bin/bash

#
# DO NOT EDIT THIS FILE
# DO NOT EDIT THIS FILE
# DO NOT EDIT THIS FILE
#
# This script externalizes the customization of the Tomcat catalina.sh 
# management shell script.  This script will scan the current working
# directory for product specific shell scripts with the name format:
#       $CATALINA_BASE/bin/<product-name>_setenv.sh
#
# For each web application or product needing customized environment
# variables a new shell script should be created with the customizations
# in it and copied into the bin directory.  The 'tcman' utility will
# automatically copy it into any instances it creates, and this script
# will find it and execut it.
#     .  %CATALINA_BASE%\bin\<product-name>_setenv.bat
# 
# The script will then load external Java options and Java system properties 
# from these files, which can be easily maintained using shell scripts and/or
# batch editors.  These files will prepend '-D' to every line that is not
# blank or a comment (starting in column zero with a pound sign #):
#       $CATALINA_BASE/conf/appserver.properties          #JAVA_OPTS values
#       $CATALINA_BASE/conf/jvm.properties                #JAVA_OPTS values
#       $CATALINA_BASE/conf/catalinaopts.properties       #CATALINA_OPTS values
#
# The product shell scripts may change or append any of the process environment
# variables found in catalina.sh, as well as adding Java system properties
# specific to the product such as the CATALINA_OPTS variable.
#
#
_status=0
_newOpts=""

# Define a place where the catalina.sh environment variables can be easily
# controlled via sed batch editing used in installs or external admin shell
# scripts.   
initCatalinaEnv () {

    # setenv.sh runs before the defaults for some CATALINA_xxxx variables
    # are set. So set the same defaults as used in catalina.sh for
    # consistency.  (CATALINA_BASE and CATALINA_HOME defaults are
    # set before setenv.sh runs)
    if [ -z "$CATALINA_TMPDIR" ] ; then
      CATALINA_TMPDIR="$CATALINA_BASE"/temp
    fi
    # Ensure a PID file is created for killing Tomcat using kill -15
    if [ "$CATALINA_PID" = "" ] ; then CATALINA_PID="$CATALINA_BASE"/temp/catalina.pid ; export CATALINA_PID ; fi

}

# Define a place where the JAVA_HOME and/or JRE_HOME process environment
# variables can be customized before executing JAVA related operations
# in catalina.sh. Because setenv is not used in all command line tools that
# require JAVA, this script will call out to the javacfg.sh script to
# do the work.
initJavaEnv () {
    if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** setenv.sh executing JAVA initialization script"; fi
    if [ -f "$CATALINA_BASE/bin/javacfg.sh" ] ; then
        . "$CATALINA_BASE/bin/javacfg.sh"
    elif [ -f "$CATALINA_HOME/bin/javacfg.sh" ] ; then
        . "$CATALINA_HOME/bin/javacfg.sh"
    fi
}

loadEnvScripts () {
    # Now find all the executable product shell scripts and execute them in 
    # the context of this shell process
    if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** setenv.sh executing product specific startup scripts"; fi
    for _fspec in `find ${CATALINA_BASE}/bin -type f -name "*_setenv.sh" -print`
    do
        if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** executing: ${_fspec}"; fi
        . ${_fspec}
    done

}

# Load a Java properties file
loadProperties () {
    if [ -f ${1} ]
    then
        _tmp="tmp-`od -N4 -tu /dev/urandom | awk 'NR==1 {print $2} {}'`"
        _tmp="${CATALINA_TMPDIR}"/${_tmp}
        _tmp="`basename $_tmp`"
        if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** setenv.sh loading ${1}"; fi
        if [ -f ${CATALINA_TMPDIR}/${_tmp} ] ; then
            rm ${CATALINA_TMPDIR}/${_tmp} ; fi

        grep '^[-,a-z,A-Z]' ${1} | while read _in
        do 
            _d="-D"
            _c=`echo ${_in} | cut -c 1`
            if [ "${_in}" != "" -a "#" != "${_c}" ]
            then
                # if the line start with '-' then use it as-is.
                # if the line does not start with '-', then prefix '-D'
                _d=""
                _inres="`(eval echo ${_in})`"
                if [ "${_c}" != "-" ] ; then 
                    _d="-D" 
                fi
                printf " %s" "${_d}${_inres}" >> "${CATALINA_TMPDIR}"/${_tmp}
            fi
        done 
    fi
    if [ -f ${CATALINA_TMPDIR}/${_tmp} ]
    then
        _newOpts="`cat \"${CATALINA_TMPDIR}\"/${_tmp}`"
        rm ${CATALINA_TMPDIR}/${_tmp}
    fi
}

# Load JVM properties from a Java properties formatted file and append to 
# the JAVA_OPTS environment variable for catalina.sh to use
loadJavaOptions () {
    _existingOpts=${JAVA_OPTS}
    _newOpts=""
    loadProperties ${CATALINA_BASE}/conf/jvm.properties

    JAVA_OPTS="$JAVA_OPTS -Djuli-logback.configurationFile=$CATALINA_BASE/conf/logging-tomcat.xml"

    if [ "${_newOpts}" != "" ] 
    then 
        if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** setenv.sh updating JAVA_OPTS with ${_newOpts} "; fi
        JAVA_OPTS="${_newOpts} ${JAVA_OPTS}" ; export JAVA_OPTS
    fi
}

# Load Java properties from a Java properties formatted file and append to 
# the JAVA_OPTS environment variable for catalina.sh to use
loadAppServerOptions () {
    _existingOpts=${JAVA_OPTS}
    _newOpts=""
    loadProperties ${CATALINA_BASE}/conf/appserver.properties

    if [ "${_newOpts}" != "" ] 
    then 
        JAVA_OPTS="${_newOpts} ${JAVA_OPTS}" ; export JAVA_OPTS
        if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** setenv.sh updating JAVA_OPTS with ${JAVA_OPTS} "; fi
    fi
}

# Load Java properties from a Java properties formatted file and append to 
# the CATALINA_OPTS environment variable for catalina.sh to use
loadCatalinaOptions () {
    _existingOpts=${CATALINA_OPTS}
    _newOpts=""
    loadProperties ${CATALINA_BASE}/conf/catalinaopts.properties

    if [ "${_newOpts}" != "" ] 
    then 
        CATALINA_OPTS="${_newOpts} ${JAVA_OPTS}" ; export CATALINA_OPTS
        if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** setenv.sh updating CATALINA_OPTS with ${CATALINA_OPTS} "; fi
    fi
}

# Load SSL TrustStore properties from catalina.properties and set as Java system properties
# Reads psc.as.https.trustfile, psc.as.https.trusttype, and psc.as.https.trustpass
# and sets javax.net.ssl.* properties
loadSSLTrustStoreProperties () {
    if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** entering loadSSLTrustStoreProperties"; fi
    
    # Check if catalina.properties exists
    if [ ! -f "${CATALINA_BASE}/conf/catalina.properties" ]; then
        return
    fi
    
    local _trustfile=""
    local _trusttype=""
    local _trustpass=""
    
    # Read properties from catalina.properties
    while IFS='=' read -r key value || [ -n "$key" ]; do
        # Skip comments and empty lines
        case "$key" in
            \#*|'')
                continue
                ;;
        esac
        
        # Trim whitespace from key
        key=$(echo "$key" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//')
        
        # Match our properties
        case "$key" in
            "psc.as.https.trustfile")
                _trustfile="$value"
                ;;
            "psc.as.https.trusttype")
                _trusttype="$value"
                ;;
            "psc.as.https.trustpass")
                _trustpass="$value"
                ;;
        esac
    done < "${CATALINA_BASE}/conf/catalina.properties"
    
    # Build absolute path for trust store file if relative
    if [ -n "$_trustfile" ]; then
        # Check if path is relative (doesn't start with /)
        # POSIX instead of bash-only ${_trustfile:0:1}: catalina.sh is #!/bin/sh and
        # sources this file, and /bin/sh is dash on Ubuntu/Debian ("Bad substitution").
        case "$_trustfile" in
            /*) ;;
            *)  _trustfile="${CATALINA_BASE}/${_trustfile}" ;;
        esac
        JAVA_OPTS="${JAVA_OPTS} -Djavax.net.ssl.trustStore=\"${_trustfile}\""
        if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** Set javax.net.ssl.trustStore=${_trustfile}"; fi
    fi
    
    # Set trust store type if found
    if [ -n "$_trusttype" ]; then
        JAVA_OPTS="${JAVA_OPTS} -Djavax.net.ssl.trustStoreType=${_trusttype}"
        if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** Set javax.net.ssl.trustStoreType=${_trusttype}"; fi
    fi
    
    # Set trust store password if found
    if [ -n "$_trustpass" ]; then
        JAVA_OPTS="${JAVA_OPTS} -Djavax.net.ssl.trustStorePassword=${_trustpass}"
        if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** Set javax.net.ssl.trustStorePassword=***"; fi
    fi
    
    export JAVA_OPTS
}

# Load the full DNS name for this server and make a java property out of if
#
loadDNSName ()  {
    if [ ! -z "${CATALINA_DEBUG}" ]; then echo "** setenv.sh updating JAVA_OPTS with DNS information "; fi
    if [ "`uname`" = "AIX" ] ; then
        _new="-n"
    else
        _new=""
    fi
	_tmpfil="$CATALINA_BASE/temp/host$$.dat"
    _hostname=`uname -n | cut -d " " -f 1`
    host ${_new} ${_hostname} > $_tmpfil 2>&1
    if [ $? = 0 ] ; then 
        _dnsname=`cat $_tmpfil | cut -d " " -f 1 | tail -1`
    else
        _dnsname="127.0.0.1"
    fi
    if [ -f $_tmpfil ] ; then
		rm $_tmpfil
	fi
    JAVA_OPTS="${JAVA_OPTS} -Dpsc.as.host.name=\"${_hostname}\" -Dpsc.as.dns.name=\"${_dnsname}\" "
    export JAVA_OPTS
}

#Add to CLASSPATH
addToClasspath() {
if [ -z "$CLASSPATH" ] 
    then
        CLASSPATH="$1"
    else 
        CLASSPATH="${CLASSPATH}:"$1""
    fi 
}


if [ ! -z "${CATALINA_DEBUG}" ]; then 
echo "dbg: setenv.sh starting with:"
echo "dbg:    CATALINA_HOME=$CATALINA_HOME"
echo "dbg:    CATALINA_BASE=$CATALINA_BASE"
echo "dbg:    CATALINA_TMPDIR=$CATALINA_TMPDIR"
echo "dbg:    WRKDIR=$WRKDIR"
echo ""
fi

initCatalinaEnv
initJavaEnv
loadEnvScripts 
loadJavaOptions
loadAppServerOptions
loadCatalinaOptions
loadSSLTrustStoreProperties
loadDNSName

